/* @lc app=leetcode id=2846 lang=kotlin */
class Solution { fun minOperationsQueries(n: Int, edges: Array<IntArray>, queries: Array<IntArray>): IntArray = Array(n) { mutableListOf<Pair<Int, Int>>() }.also { adj -> edges.forEach { edge -> adj[edge[0]].add(edge[1] to edge[2]).also { adj[edge[1]].add(edge[0] to edge[2]) } } }.let { adj -> Array(15) { IntArray(n) }.let { up -> Array(n) { IntArray(27) }.let { freq -> IntArray(n).let { depth -> java.util.ArrayDeque<Int>().apply { add(0) }.let { q -> generateSequence { q.poll() }.forEach { u -> adj[u].forEach { p -> p.first.let { v -> p.second.let { w -> if (v != up[0][u]) up[0][v].also { up[0][v] = u }.also { depth[v] = depth[u] + 1 }.also { (1..26).forEach { c -> freq[v][c] = freq[u][c] } }.also { freq[v][w]++ }.also { q.add(v) } } } } }.let { (1..14).forEach { i -> (0 until n).forEach { j -> up[i][j] = up[i - 1][up[i - 1][j]] } } }.let { { a: Int, b: Int -> (if (depth[a] >= depth[b]) a to b else b to a).let { pair -> (14 downTo 0).fold(pair.first) { currU, i -> if (depth[currU] - (1 shl i) >= depth[pair.second]) up[i][currU] else currU }.let { u -> if (u == pair.second) u else (14 downTo 0).fold(u to pair.second) { curr, i -> if (up[i][curr.first] != up[i][curr.second]) up[i][curr.first] to up[i][curr.second] else curr }.let { last -> up[0][last.first] } } } } }.let { lca -> queries.map { qry -> lca(qry[0], qry[1]).let { w -> (depth[qry[0]] + depth[qry[1]] - 2 * depth[w]) - (1..26).maxOf { c -> freq[qry[0]][c] + freq[qry[1]][c] - 2 * freq[w][c] } } }.toIntArray() } } } } } }